 void releasePlayer(){generation++;if(timeout!=null)handler.removeCallbacks(timeout);timeout=null;if(retry!=null)handler.removeCallbacks(retry);retry=null;if(player!=null){player.release();player=null;}prepared=false;if(subtitles!=null)subtitles.setCues(Collections.emptyList());}
